	oldunovapokedex: {
		effectType: "ValidatorRule",
		name: "Old Unova Pokedex",
		desc: "Only allows Pok&eacute;mon native to the Unova region as of the original Black/White games",
		onValidateSet(t, e) {
			let a = this.dex.species.get(t.species || t.name);
			if (!(a.num >= 494 && a.num <= 649 && ![
				"Black",
				"White",
				"Therian",
				"Resolute"
			].includes(a.forme) && a.gen <= 5) && !this.ruleTable.has("+" + a.id)) return [`${a.baseSpecies} is not in the Old Unova Pok\xE9dex.`];
		}
	},
