	potd: {
		effectType: "Rule",
		name: "PotD",
		desc: "Forces the Pokemon of the Day onto every random team.",
		onBegin() {
			global.Config?.potd && this.add("rule", "Pokemon of the Day: " + this.dex.species.get(global.Config.potd).name);
		}
	},
	forcemonotype: {
		effectType: "ValidatorRule",
		name: "Force Monotype",
		desc: "Forces all teams to have the same type. Usage: Force Monotype = [Type], e.g. \"Force Monotype = Water\"",
		hasValue: !0,
		onValidateRule(t) {
			let e = this.dex.types.get(t);
			if (!e.exists) throw new Error(`Misspelled type "${t}"`);
			if (["Dark", "Steel"].includes(e.name) && this.dex.gen < 2 || e.name === "Fairy" && this.dex.gen < 6) throw new Error(`Invalid type "${e.name}" in Generation ${this.dex.gen}`);
			if (e.name === "Stellar") throw new Error("There are no Stellar-type Pokémon.");
			return e.name;
		},
		onValidateSet(t) {
			let e = this.dex.species.get(t.species), a = this.dex.types.get(this.ruleTable.valueRules.get("forcemonotype"));
			if (!e.types.map(this.toID).includes(a.id)) return [`${t.species} must have ${a.name} type.`];
		}
	},
